namespace ScipSharp.Indexer.Dart.Tests;

/// <summary>
/// Compares our output with the upstream scip-dart snapshots (generated by the Dart analyzer). Definitions of
/// non-local symbols must match exactly; references are compared for precision only because this indexer has no
/// type information (instance member access, SDK symbols and diagnostics are out of scope).
/// </summary>
public class SnapshotParityTests
{
    public static IEnumerable<(string Project, string File)> DartFiles()
    {
        foreach (var project in new[] { "basic-project", "dart3-features" })
        {
            var output = Fixtures.Output(project);
            foreach (var file in Directory.EnumerateFiles(output, "*.dart", SearchOption.AllDirectories))
            {
                yield return (project, Path.GetRelativePath(output, file).Replace('\\', '/'));
            }
        }
    }

    [Test]
    [MethodDataSource(nameof(DartFiles))]
    public async Task DefinitionsMatchUpstreamSnapshot(string project, string file)
    {
        var index = DartIndexer.Build(Fixtures.Input(project), indexPubspec: true);
        var doc = index.Documents.Single(d => d.RelativePath == file);
        var source = await File.ReadAllTextAsync(Path.Combine(Fixtures.Input(project), file));

        var expected = UpstreamSnapshot.Definitions(await File.ReadAllTextAsync(Path.Combine(Fixtures.Output(project), file)));
        var actual = UpstreamSnapshot.Definitions(SnapshotRenderer.Render(doc, source));

        await Assert.That(expected.Except(actual).Order().ToList()).IsEmpty();
        await Assert.That(actual.Except(expected).Order().ToList()).IsEmpty();
    }

    [Test]
    public async Task ReferencesToProjectSymbolsAreMostlyPrecise()
    {
        const string project = "basic-project";
        var index = DartIndexer.Build(Fixtures.Input(project));
        int ours = 0, correct = 0, upstream = 0, found = 0;
        foreach (var (_, file) in DartFiles().Where(f => f.Project == project))
        {
            var doc = index.Documents.Single(d => d.RelativePath == file);
            var source = await File.ReadAllTextAsync(Path.Combine(Fixtures.Input(project), file));
            var expected = UpstreamSnapshot.Definitions(await File.ReadAllTextAsync(Path.Combine(Fixtures.Output(project), file)), "reference")
                .Where(x => x.Contains(" dart_test ")).ToHashSet();
            var actual = UpstreamSnapshot.Definitions(SnapshotRenderer.Render(doc, source), "reference")
                .Where(x => x.Contains(" dart_test ")).ToHashSet();
            ours += actual.Count;
            correct += actual.Intersect(expected).Count();
            upstream += expected.Count;
            found += expected.Intersect(actual).Count();
        }

        // Documented coverage: a bit over half of own-package references are found; nearly all we emit are right.
        await Assert.That(correct / (double)ours).IsGreaterThan(0.9);
        await Assert.That(found / (double)upstream).IsGreaterThan(0.5);
    }
}
